argv:
$ErrorActionPreference='SilentlyContinue'
$startupUser=[Environment]::GetFolderPath('Startup')
$startupAll="$env:ProgramData\Microsoft\Windows\Start Menu\Programs\Startup"
$runUser=Get-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
$runAll=Get-ItemProperty 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Run'
$tasks=Get-ScheduledTask | Where-Object {
  ($_.TaskName -match 'pc|control|bridge|chrome|webai|relay|mcp') -or
  (($_.Actions | Out-String) -match 'chrome|WebAIBridge|pc-github-relay|PC-Control|mcp')
} | ForEach-Object {
  [pscustomobject]@{
    TaskName=$_.TaskName;TaskPath=$_.TaskPath;State=$_.State;
    Actions=(($_.Actions | ForEach-Object { "$($_.Execute) $($_.Arguments)" }) -join ' | ');
    Triggers=(($_.Triggers | ForEach-Object { $_.CimClass.CimClassName+':'+$_.Enabled }) -join ' | ')
  }
}
$services=Get-CimInstance Win32_Service | Where-Object {
  $_.Name -match 'pc|control|bridge|relay|mcp|webai' -or $_.DisplayName -match 'pc|control|bridge|relay|mcp|webai' -or $_.PathName -match 'pc-github-relay|PC-Control|WebAIBridge'
} | Select-Object Name,DisplayName,StartMode,State,PathName
$procs=Get-CimInstance Win32_Process | Where-Object {
  $_.Name -match 'chrome|node|python|powershell|cmd' -and
  $_.CommandLine -notmatch 'E:\\manhwa'
} | Select-Object ProcessId,ParentProcessId,Name,CommandLine
[pscustomobject]@{
  StartupUser=$startupUser
  StartupUserFiles=@(Get-ChildItem $startupUser -Force | Select-Object Name,FullName)
  StartupAll=$startupAll
  StartupAllFiles=@(Get-ChildItem $startupAll -Force | Select-Object Name,FullName)
  RunUser=@($runUser.PSObject.Properties | Where-Object {$_.Name -notmatch '^PS'} | Select-Object Name,Value)
  RunAll=@($runAll.PSObject.Properties | Where-Object {$_.Name -notmatch '^PS'} | Select-Object Name,Value)
  Tasks=@($tasks)
  Services=@($services)
  Processes=@($procs)
} | ConvertTo-Json -Depth 7 -Compress
